sources.app.tsx:
// Road racer: a pseudo-3D race against the clock in the 8-bit palette mode.
// The road curves and climbs over hills through forests, meadows and rocks;
// overtake the traffic, keep off the grass, and reach each checkpoint before
// the time runs out. Every lap the day goes on: dusk, then night, then day.
//
// The road is drawn a screen row at a time into one Uint8Array of cells for
// frameos.pixels (game.ts). Touch: the arrows steer and A / B are gas and
// brake (gas is automatic unless you play with a keyboard), or hold the left
// or the right half of the road to steer. Keys: arrows or A / D steer, Up, W,
// Space or Z for gas, Down, S or X to brake, Enter or P to pause. GPIO
// buttons by the "Buttons" setting.
import { clip, fill, target, textCenter, textWidth, title } from './gfx'
import {
  A, B, DOWN, START, TAP, UP, dragging, handle, held as heldNow, keyAction, lastTapX, lastTapY, press, ptrX,
  releaseAll, setButtons, setHitTest, take, usingKeyboard,
} from './input'
import { drawControls, hit, layout, roundLayout, updateControls } from './controls'
import {
  UI_ACCENT, UI_BLINK, UI_DIALOG, UI_DIM, UI_PANEL, UI_SHADOW, UI_TITLE, addScore, blink, cellSize, choice, clockReset,
  dialog, drawGameOver, drawPause, drawScores, drawSlowCard, fastScreen, fitScale, highContrast, pauseChoice,
  readScores, reseed, stepsDue, uiColors,
} from './ui'
import { THEME, gameColors } from './art'
import { S, VIEW, attract, drawHud, frame, newRace, resume, setBest, setView, snapshot, takeLap } from './game'

const STEP_MS = 1000 / 60
const IDLE_MS = 30000 // the title and game over animate this long, then sleep until a touch

let cells: Uint8Array | null = null
let cols = 0
let rows = 0
let px = 5
let width = 0
let height = 0
let L: any = null
let round = false // a round panel's whole canvas (context.round)
const pal = new Uint32Array(256)
const opts = { width: 1, height: 1, pixelSize: 1 }

type Mode = 'title' | 'play' | 'pause' | 'over' | 'slow'
let mode: Mode = 'title'
let idleFrom = 0
let shownHeld = 0
let scores: number[] = []
let rank = -1
let overAt = 0
let overReady = false
let snapAt = 0

// Settings, read from the scene's state about once a second.
let settingsAt = 0
let layoutKey = ''
let hc = false
let fast = true
let difficulty = 1
let traffic = 2
let autoGas = 'auto'
let timeOfDay = 'cycle'
// The time of day shown (0 day, 1 dusk, 2 night, fractions between) and where it is going.
let phase = 0
let phaseTo = 0
let shownPhase = -1

// Up and Down are gas and brake on a keyboard.
function keys(code: string): number {
  const bits = keyAction(code)
  return bits === UP ? A : bits === DOWN ? B : bits
}

export function get(app, context) {
  const now = Date.now()
  const w = context.imageWidth || app.frame.width
  const h = context.imageHeight || app.frame.height
  round = context.round === true
  if (!cells || w !== width || h !== height || now - settingsAt > 1000) settings(app, w, h, now)
  if (mode === 'slow') {
    frameos.setNextSleep(3600)
    return frameos.pixels(cells!, pal, opts)
  }
  let pressed = take()
  const held = heldNow()
  // A press that changes the mode is spent on that.
  if (mode === 'title') {
    if (pressed & (A | START | TAP)) {
      start(now)
      pressed = 0
    } else {
      frame(stepsDue(now, STEP_MS, 4), 0, false, 0, true)
      titleOverlay(now)
    }
  } else if (mode === 'pause') {
    let pick = 0
    if (pressed & TAP) pick = pauseChoice(lastTapX() / px, lastTapY() / px)
    if (pick === 1 || pressed & (A | START)) unpause(now)
    else if (pick === 2 || pressed & B) quit(now)
    pressed = 0
  } else if (mode === 'over') {
    if (!overReady && now - overAt > 1200) {
      overReady = true
      overDialog()
    }
    if (overReady && pressed & (A | START | TAP)) start(now)
    else if (overReady && pressed & B) quit(now)
    pressed = 0
  }
  if (mode === 'play') {
    if (pressed & START) pause()
    else play(now, held)
  }
  colors(now)
  if (L && held !== shownHeld) {
    updateControls(L, shownHeld, held)
    shownHeld = held
  }
  if (mode === 'pause' || ((mode === 'title' || mode === 'over') && now - idleFrom > IDLE_MS)) frameos.setNextSleep(3600)
  return frameos.pixels(cells!, pal, opts)
}

export function onEvent(app, context) {
  const event = context.event
  if (event === 'close') {
    // Every finger lets go, and a game going on pauses.
    releaseAll()
    if (mode === 'play') press(START)
    return false
  }
  if (event === 'open') return mode !== 'slow'
  if (event === 'back') press(START)
  else if (event === 'forward') press(mode === 'play' ? 0 : A)
  else if (handle(event, context.payload || {}, keys) < 0) return false
  idleFrom = Date.now()
  return mode !== 'play' && mode !== 'slow'
}

// --- settings and the layout ---------------------------------------------------------------

function settings(app: any, w: number, h: number, now: number) {
  settingsAt = now
  const st = app.state
  const frame = app.frame
  const fresh = !cells
  if (fresh) scores = readScores(st.highScores)
  hc = highContrast(st.contrast, frame)
  fast = fastScreen(frame)
  difficulty = ['easy', 'normal', 'hard'].indexOf(choice(st.difficulty, ['normal', 'easy', 'hard']))
  traffic = ['none', 'light', 'normal', 'heavy'].indexOf(choice(st.traffic, ['normal', 'none', 'light', 'heavy']))
  autoGas = choice(st.autoGas, ['auto', 'on', 'off'])
  timeOfDay = choice(st.timeOfDay, ['cycle', 'day', 'dusk', 'night'])
  setButtons(st.buttons)
  // Round: smaller cells, so a pause dialog fits the view above the buttons (a round canvas has fewer anyway).
  const size = cellSize(st.pixelSize, w, h, round ? 120 : 96)
  const show = choice(st.controls, ['on', 'off']) === 'on'
  uiColors(pal, THEME, hc)
  shownPhase = -1
  const key = [w, h, size, show, fast, round].join(':')
  if (key === layoutKey && !fresh) return
  layoutKey = key
  width = w
  height = h
  px = size
  cols = Math.max(40, Math.floor(w / px))
  rows = Math.max(40, Math.floor(h / px))
  cells = new Uint8Array(cols * rows)
  opts.width = cols
  opts.height = rows
  opts.pixelSize = px
  target(cells, cols, rows)
  if (!fast) {
    mode = 'slow'
    gameColors(pal, 0, hc)
    drawSlowCard(cols, rows, 'ROAD RACER', ['A RACE AGAINST THE CLOCK', 'FOR A FAST SCREEN: LCD OR HDMI.', '',
      'ON E-PAPER IT SLEEPS HERE.'], scores)
    return
  }
  // A bar along the bottom on every screen: the road wants the width.
  L = round ? roundLayout(cols, rows, px, 2, 2, show, 'A', 'B', false, 'ROAD RACER') : layout(cols, rows, px, 2, 2, show, 'A', 'B', false)
  const layoutNow = L
  setHitTest((x, y) => hit(layoutNow, x, y))
  setView(cells, cols, L.x, L.y, L.w, L.h)
  setBest(scores.length ? scores[0] : 0)
  if (fresh) {
    reseed(now)
    idleFrom = now
    const snap = frameos.recall('snap') as any
    if (snap && snap.lap) {
      resume(snap, difficulty, traffic)
      mode = 'pause'
    } else {
      mode = 'title'
      attract()
    }
  } else if (mode === 'play') mode = 'pause'
  if (mode === 'slow') {
    mode = 'title'
    attract()
  }
  drawEverything()
}

function drawEverything() {
  cells!.fill(UI_PANEL)
  clip(0, 0, cols, rows)
  drawControls(L, heldNow())
  shownHeld = heldNow()
  drawHud(true, mode !== 'title')
  frame(0, 0, false, 0, mode === 'title')
  if (mode === 'pause') pauseDialog()
  else if (mode === 'over') overDialog()
}

// --- the modes -------------------------------------------------------------------------------

function start(now: number) {
  newRace(difficulty, traffic)
  mode = 'play'
  rank = -1
  clockReset(now)
  if (timeOfDay === 'cycle') phase = phaseTo = 0
  drawHud(true, true)
}

function play(now: number, held: number) {
  const gas = autoGas === 'on' || (autoGas === 'auto' && !usingKeyboard())
  // A finger on the road steers: left or right of the middle.
  const drag = dragging()
  let pointer = 0
  if (drag >= 0) {
    const x = ptrX[drag] / px - VIEW[0]
    pointer = x < VIEW[2] * 0.42 ? -1 : x > VIEW[2] * 0.58 ? 1 : 0
  }
  frame(stepsDue(now, STEP_MS, 4), held, gas, pointer, false)
  drawHud(false, true)
  if (takeLap() && timeOfDay === 'cycle') phaseTo += 1
  if (S.over) {
    mode = 'over'
    overAt = now
    overReady = false
    idleFrom = now
    rank = addScore(scores, S.score)
    setBest(scores.length ? scores[0] : 0)
    frameos.remember('snap', null)
    overDialog()
    return
  }
  if (now - snapAt > 1000) {
    snapAt = now
    frameos.remember('snap', snapshot())
  }
}

function pause() {
  mode = 'pause'
  releaseAll()
  frameos.remember('snap', snapshot())
  pauseDialog()
}

function unpause(now: number) {
  mode = 'play'
  clockReset(now)
}

function quit(now: number) {
  mode = 'title'
  idleFrom = now
  frameos.remember('snap', null)
  attract()
  drawHud(true, false)
}

function pauseDialog() {
  clip(VIEW[0], VIEW[1], VIEW[2], VIEW[3])
  drawPause(VIEW[0], VIEW[1], VIEW[2], VIEW[3], 'ENTER OR P: RESUME')
}

function overDialog() {
  clip(VIEW[0], VIEW[1], VIEW[2], VIEW[3])
  drawGameOver(VIEW[0], VIEW[1], VIEW[2], VIEW[3], 'TIME UP', ['SCORE ' + S.score, 'LAP ' + S.lap], rank, scores,
    overReady)
}

/** Over the title's drive: the name, then the high scores, taking turns. */
function titleOverlay(now: number) {
  const vx = VIEW[0]
  const vy = VIEW[1]
  const vw = VIEW[2]
  const vh = VIEW[3]
  clip(vx, vy, vw, vh)
  const cx = vx + (vw >> 1)
  const small = fitScale(24, vw - 4, 2)
  if ((((now - idleFrom) / 6000) | 0) & 1 && scores.length) {
    const s = small
    const bw = Math.min(vw - 4, 64 * s)
    const bh = Math.min(vh - 4, (12 + scores.length * 7) * s)
    dialog(cx - (bw >> 1), vy + 3, bw, bh)
    drawScores(scores, cx, vy + 3 + 3 * s, s)
  } else {
    const big = Math.max(1, Math.min(fitScale(10, vw - 6, 4), Math.floor(vh / 4 / 6)))
    title('ROAD RACER', cx, vy + 3 + big, big, UI_TITLE, UI_SHADOW)
    const tag = 'BEAT THE CLOCK'
    const ty = vy + 4 + 7 * big
    fill(cx - (textWidth(tag, small) >> 1) - 2, ty - 2, textWidth(tag, small) + 4, 5 * small + 4, UI_DIALOG)
    textCenter(tag, cx, ty, small, UI_ACCENT)
  }
  const label = 'TAP OR PRESS A'
  const y = vy + ((vh * 0.6) | 0)
  fill(cx - (textWidth(label, small) >> 1) - 2, y - 2, textWidth(label, small) + 4, 5 * small + 4, UI_DIALOG)
  textCenter(label, cx, y, small, UI_BLINK)
  if (vh > 70 && textWidth('A GAS  B BRAKE', 1) < vw - 4) textCenter('A GAS  B BRAKE', cx, y + 6 * small + 2, 1, UI_DIM)
}

// --- colors -------------------------------------------------------------------------------------

function colors(now: number) {
  const fixed = timeOfDay === 'day' ? 0 : timeOfDay === 'dusk' ? 1 : timeOfDay === 'night' ? 2 : -1
  if (fixed >= 0) phase = phaseTo = fixed
  // A new lap: the light changes over three seconds.
  else if (phase < phaseTo) phase = Math.min(phaseTo, phase + 1 / 90)
  if (phase !== shownPhase) {
    shownPhase = phase
    gameColors(pal, phase, hc)
  }
  blink(pal, now, hc ? 0xffffff : THEME.text, hc ? 0 : THEME.dim)
}

sources.art.ts:
// Road racer's colors and sprites. Each palette index is one thing's color in
// three palettes (day, dusk and night); a lap changes the time of day by
// blending one palette into the next, which costs no cell. Sprites are
// compact strings, left half and middle column only where they are
// symmetric: the right half is the left one turned over.
import { sprite } from './gfx'

export const SKY = 0 // .. 7, the top of the sky down to the horizon
export const SUN = 8
export const CLOUD = 9
export const MOUNT = 10
export const HILL = 11
export const GROUND = 12
export const GRASS_L = 13
export const GRASS_D = 14
export const RUMBLE_L = 15
export const RUMBLE_D = 16
export const ROAD_L = 17
export const ROAD_D = 18
export const LANE = 19
export const PINE = 20
export const PINE_D = 21
export const TRUNK = 22
export const LEAF = 23
export const LEAF_D = 24
export const ROCK = 25
export const ROCK_D = 26
export const SIGN = 27
export const SIGN_INK = 28
export const POST = 29
export const CAR_A = 30 // body, shade: three traffic colors
export const CAR_A_D = 31
export const CAR_B = 32
export const CAR_B_D = 33
export const CAR_C = 34
export const CAR_C_D = 35
export const WINDOW = 36
export const TIRE = 37
export const TAIL = 38
export const PLAYER = 39
export const PLAYER_D = 40
export const STRIPE = 41
export const BANNER = 42
export const BANNER_2 = 43
export const HUD = 44
export const HUD_TEXT = 45
export const HUD_DIM = 46
export const TIME = 47
export const WARN = 48
export const DUST = 49
export const COUNT = 50

// Day, dusk and night, index by index.
const DAY = [
  0x2f6fd0, 0x3f80da, 0x5592e2, 0x6aa4e8, 0x80b6ee, 0x95c6f2, 0xaad4f5, 0xc0e2f8,
  0xfff5c0, 0xffffff, 0x8a9cc8, 0x4f8a5c, 0x5d9a48,
  0x63b043, 0x58a03a, 0xf2f2f2, 0xd03a3a, 0x75757e, 0x6c6c75, 0xf6f6f6,
  0x2f7a3a, 0x1f5a2a, 0x7a4a2a, 0x58a83a, 0x3a7a2a, 0x9a948a, 0x6a645c, 0xffd23a, 0x2a2a2a, 0x8a8a8a,
  0xd8323a, 0x8a1a22, 0x2f6fd8, 0x1a3a88, 0xf2c230, 0xa07a10, 0x1a2a3a, 0x18181c, 0xff4a3a,
  0xf4f4f8, 0xa0a4b4, 0xe8364a,
  0xf4f4f4, 0x202024, 0x0e1a2e, 0xf4f8ff, 0x8aa0c8, 0xffe14a, 0xff4a4a, 0xc8b89a,
]
const DUSK = [
  0x231a48, 0x3a2058, 0x5a2a66, 0x7e3468, 0xa84468, 0xd05a5e, 0xf07a52, 0xffa258,
  0xffd27a, 0xf8a08a, 0x5a3a6e, 0x3a2e50, 0x4a4a3a,
  0x5e7a34, 0x52702c, 0xf0e2d0, 0xc03a3a, 0x5c5862, 0x55515b, 0xffe2b0,
  0x2a5a34, 0x1c4226, 0x5a3a24, 0x4e7e32, 0x365a26, 0x7e7068, 0x56484a, 0xf2b23a, 0x2a2026, 0x6a6266,
  0xc82e38, 0x7a1a24, 0x3a5ac8, 0x1e2e70, 0xe8a830, 0x8a5a14, 0x2a1a30, 0x141016, 0xff5a3a,
  0xf0e8e8, 0x988ca0, 0xe8364a,
  0xf0e0d0, 0x2a2026, 0x1a1028, 0xfff0e0, 0xb090a8, 0xffd04a, 0xff5050, 0xa08470,
]
const NIGHT = [
  0x03040e, 0x050818, 0x080c22, 0x0b122c, 0x0e1736, 0x121d40, 0x16234a, 0x1c2c56,
  0xe8ecff, 0x1a2244, 0x222a4a, 0x10162a, 0x0e1a14,
  0x1c3a22, 0x17321c, 0xa0a0b0, 0x8a2a2a, 0x34343e, 0x2e2e38, 0xe0e0a8,
  0x123a20, 0x0a2614, 0x2a1c14, 0x1a4a22, 0x103418, 0x4a4a52, 0x30303a, 0xd0a83a, 0x141418, 0x4a4a52,
  0xa82a32, 0x5a141a, 0x2a4ab0, 0x141e5a, 0xc8962a, 0x6a4a10, 0x8ad0ff, 0x08080a, 0xff3a2a,
  0xd8dce8, 0x6a6e80, 0xd02e40,
  0xd8d8e0, 0x18181e, 0x060a18, 0xe8ecff, 0x6a78a8, 0xffe14a, 0xff4a4a, 0x5a5468,
]
export const PALETTES = [DAY, DUSK, NIGHT]
// In black and white: 1 white, 0 black.
const INK = '00000000100011110001010010101010101001010010011111'

/** The game's colors at `phase` (0 day, 1 dusk, 2 night, fractions between). */
export function gameColors(pal: Uint32Array, phase: number, hc: boolean) {
  if (hc) {
    for (let i = 0; i < COUNT; i++) pal[i] = INK[i] === '1' ? 0xffffff : 0
    return
  }
  const a = (phase | 0) % 3
  const b = (a + 1) % 3
  const t = phase - (phase | 0)
  const A = PALETTES[a]
  const B = PALETTES[b]
  for (let i = 0; i < COUNT; i++) {
    const ca = A[i]
    if (t === 0) {
      pal[i] = ca
      continue
    }
    const cb = B[i]
    const r = ((ca >> 16) & 255) + ((((cb >> 16) & 255) - ((ca >> 16) & 255)) * t)
    const g = ((ca >> 8) & 255) + ((((cb >> 8) & 255) - ((ca >> 8) & 255)) * t)
    const bl = (ca & 255) + (((cb & 255) - (ca & 255)) * t)
    pal[i] = ((r | 0) << 16) | ((g | 0) << 8) | (bl | 0)
  }
}

export const THEME = {
  title: [0xfff6a0, 0xffd84a, 0xff9a3a, 0xff5a3a, 0xd8325a],
  shadow: 0x2a1238,
  panel: 0x15151d,
  edge: 0x3a3a4c,
  border: 0x6a6a80,
  face: 0x2a2a38,
  lit: 0xffb43a,
  icon: 0xe0e0ec,
  iconLit: 0x1a1018,
  text: 0xf4f4f8,
  dim: 0x9a9ab0,
  dialog: 0x1a1a26,
  dialogEdge: 0x8a8aa8,
  accent: 0xffb43a,
  good: 0xffe14a,
}

function sym(rows: string[]): string {
  return rows.map((r) => r + r.slice(0, -1).split('').reverse().join('')).join('|')
}

// Roadside things, each with how wide it is in the world (the road is 2000).
export const PINE_S = sprite(sym(['...g', '..gg', '..gG', '.ggg', '..gG', '.ggg', 'ggGg', '.ggg', 'gggg', 'gGgg', '...t', '...t']),
  'gGt', [PINE, PINE_D, TRUNK])
export const OAK_S = sprite(sym(['..lll', '.lLll', 'lllLl', 'lLlll', '.lllL', '..lll', '....t', '....t', '...tt']),
  'lLt', [LEAF, LEAF_D, TRUNK])
export const ROCK_S = sprite(sym(['..rr', '.rRr', 'rrrR', 'rRrr']), 'rR', [ROCK, ROCK_D])
export const BUSH_S = sprite(sym(['.ll', 'lLl', 'llL']), 'lL', [LEAF, LEAF_D])
export const SIGN_L = sprite('yyyyyyy|yykyyyy|ykkkkky|yykyyyy|yyyyyyy|...p...|...p...|...p...', 'ykp', [SIGN, SIGN_INK, POST])
export const SIGN_R = sprite('yyyyyyy|yyyykyy|ykkkkky|yyyykyy|yyyyyyy|...p...|...p...|...p...', 'ykp', [SIGN, SIGN_INK, POST])

/** A car seen from behind, in body color `b` and shade `d`. */
function car(b: number, d: number) {
  return sprite(sym(['..bbbb', '.bwwww', '.bwwww', 'bbbbbb', 'btbbbb', 'bddddd', 'kk....']), 'bwtdk',
    [b, WINDOW, TAIL, d, TIRE])
}
export const CARS = [car(CAR_A, CAR_A_D), car(CAR_B, CAR_B_D), car(CAR_C, CAR_C_D)]

// The player's roadster: straight, and leaning into a left or a right turn.
const ROADSTER = ['......bbbb', '.....bwwww', '....bwwwww', '..bbbbbbbb', '.bbbbbbbbs', 'bbtttbbbbs', 'bbbbbbdddd',
  'kkkk......', 'kkkk......']
export const PLAYER_S = sprite(sym(ROADSTER), 'bwtdks', [PLAYER, WINDOW, TAIL, PLAYER_D, TIRE, STRIPE])
function lean(dir: number) {
  const rows = sym(ROADSTER).split('|')
  for (let r = 0; r < 3; r++) rows[r] = dir < 0 ? rows[r].slice(1) + '.' : '.' + rows[r].slice(0, -1)
  return sprite(rows.join('|'), 'bwtdks', [PLAYER, WINDOW, TAIL, PLAYER_D, TIRE, STRIPE])
}
export const PLAYER_LEFT = lean(-1)
export const PLAYER_RIGHT = lean(1)

// Kinds of roadside things: their sprite and width in the world.
export const KIND_SPRITES = [PINE_S, OAK_S, ROCK_S, BUSH_S, SIGN_L, SIGN_R]
export const KIND_WIDTH = [700, 1000, 520, 600, 420, 420]
export const K_PINE = 0
export const K_OAK = 1
export const K_ROCK = 2
export const K_BUSH = 3
export const K_SIGN_L = 4
export const K_SIGN_R = 5

sources.game.ts:
// Road racer's world and its drawing: a road of segments with curves and
// hills, projected the classic way (each segment's two ends through a
// camera above the car), drawn a screen row at a time into the cells. A row
// of road is a handful of runs (grass, rumble strip, asphalt, lane marks,
// rumble, grass), each one native Uint8Array.fill. Nearer segments are drawn
// first and each takes only the rows above the last, so a hill hides what is
// behind it; the sky and the mountains fill what is left, and the roadside
// things and the traffic are drawn far to near, cut off where a hill's crest
// hides them.
import { clip, fill, number, text, textCenter, textWidth, title } from './gfx'
import { A, B, LEFT, RIGHT } from './input'
import { UI_SHADOW, UI_TITLE, reseed, rfloat, rint } from './ui'
import {
  BANNER, BANNER_2, CARS, CLOUD, DUST, GRASS_D, GRASS_L, GROUND, HILL, HUD, HUD_DIM, HUD_TEXT, KIND_SPRITES, KIND_WIDTH,
  K_BUSH, K_OAK, K_PINE, K_ROCK, K_SIGN_L, K_SIGN_R, LANE, MOUNT, PLAYER_LEFT, PLAYER_RIGHT, PLAYER_S, POST, ROAD_D,
  ROAD_L, RUMBLE_D, RUMBLE_L, SKY, SUN, TIME, WARN,
} from './art'

// --- the world ------------------------------------------------------------------------

const SEG = 200 // a segment's length
const ROAD_W = 1000 // half the road's width
const CAM_H = 1000 // the camera, above the road
const DEPTH = 0.84 // 1 / tan(half the field of view)
const PLAYER_Z = CAM_H * DEPTH // from the camera to the car
const DRAW = 64 // segments drawn ahead
const N = 1440 // segments in a lap
const TRACK = N * SEG
const MAX_SPEED = SEG * 60 * 0.85 // a little under a segment a step
const DT = 1 / 60

const segCurve = new Float32Array(N)
const segY = new Float32Array(N + 1)
const sprA = new Int8Array(N).fill(-1)
const sprAX = new Float32Array(N)
const sprB = new Int8Array(N).fill(-1)
const sprBX = new Float32Array(N)
const segMark = new Uint8Array(N) // 1 the start line, 2 a checkpoint
let built = 0
let lastY = 0

function addSegment(curve: number, y: number) {
  if (built >= N) return
  segCurve[built] = curve
  segY[built] = lastY
  lastY = y
  built++
}

function easeIn(a: number, b: number, t: number) {
  return a + (b - a) * t * t
}
function easeInOut(a: number, b: number, t: number) {
  return a + (b - a) * (0.5 - Math.cos(t * Math.PI) / 2)
}

/** A stretch of road: `enter` segments easing into `curve`, `hold` of it,
 *  `leave` easing out, rising (or falling) `hill` x a segment's length. */
function addRoad(enter: number, hold: number, leave: number, curve: number, hill: number) {
  const startY = lastY
  const endY = startY + hill * SEG
  const total = enter + hold + leave
  for (let n = 0; n < enter; n++) addSegment(easeIn(0, curve, n / enter), easeInOut(startY, endY, n / total))
  for (let n = 0; n < hold; n++) addSegment(curve, easeInOut(startY, endY, (enter + n) / total))
  for (let n = 0; n < leave; n++) addSegment(easeInOut(curve, 0, n / leave), easeInOut(startY, endY, (enter + hold + n) / total))
}

// The course: enter, hold, leave, curve (+ right, - left), hill (+ up), five
// numbers a stretch.
const COURSE = '0,30,0,0,0 20,40,20,0,18 20,30,20,-3,0 20,40,20,0,-18 25,50,25,4,10 20,20,20,-2,-10 ' +
  '15,25,15,5,0 15,25,15,-5,0 30,40,30,0,28 20,40,20,3,-28 10,15,10,-4,0 10,15,10,4,0 10,15,10,-4,0 ' +
  '30,30,30,0,14 25,40,25,-3,-14 20,50,20,2,0 15,20,15,-6,6 20,40,20,0,-6 25,60,25,3,0 20,20,20,0,22 ' +
  '20,30,20,-4,-22 10,20,10,5,0 10,20,10,-5,0 30,40,30,0,0'

function buildTrack() {
  if (built) return
  for (const part of COURSE.split(' ')) {
    const v = part.split(',')
    addRoad(+v[0], +v[1], +v[2], +v[3], +v[4])
  }
  // Level again into the start line, then straight to the end of the lap.
  const left = N - built
  const y0 = lastY
  for (let n = 0; n < left; n++) addSegment(0, easeInOut(y0, 0, (n + 1) / left))
  segY[N] = segY[0]
  // The roadside: the same every game (a seeded generator), forests and
  // rocky stretches, a sign on the outside before each curve.
  reseed(20261118)
  for (let i = 8; i < N; i++) {
    const zone = ((i / 160) | 0) % 4 // 0 forest, 1 meadow, 2 rocks, 3 mixed
    if (i % 3 === 0 && rint(100) < (zone === 1 ? 45 : 80)) {
      const roll = rint(100)
      const k = zone === 0 ? (roll < 70 ? K_PINE : roll < 90 ? K_OAK : K_BUSH)
        : zone === 1 ? (roll < 50 ? K_BUSH : roll < 80 ? K_OAK : K_PINE)
        : zone === 2 ? (roll < 60 ? K_ROCK : roll < 80 ? K_BUSH : K_PINE)
        : (roll < 30 ? K_PINE : roll < 55 ? K_OAK : roll < 80 ? K_ROCK : K_BUSH)
      const side = rint(2) ? 1 : -1
      sprA[i] = k
      sprAX[i] = side * (1.35 + rfloat() * 1.6)
      if (rint(100) < 55) {
        sprB[i] = k === K_ROCK ? K_BUSH : k
        sprBX[i] = -side * (1.35 + rfloat() * 1.8)
      }
    }
    // A curve ahead: signs pointing its way.
    if (segCurve[i] === 0 && i + 40 < N && segCurve[i + 40] !== 0 && segCurve[i + 39] === 0) {
      for (let k = 0; k < 4; k++) {
        const at = i + k * 8
        sprA[at] = segCurve[i + 40] > 0 ? K_SIGN_R : K_SIGN_L
        sprAX[at] = segCurve[i + 40] > 0 ? -1.25 : 1.25
      }
    }
  }
  for (let i = 0; i < 4; i++) sprA[i] = sprB[i] = -1
  segMark[0] = 1
  segMark[(N / 3) | 0] = 2
  segMark[((2 * N) / 3) | 0] = 2
}

// --- the view and the background ----------------------------------------------------------

let cells: Uint8Array = new Uint8Array(1)
let cols = 1
let VX = 0 // the road's view, in cells
let VY = 0
let VW = 1
let VH = 1
let HY = 0 // the score strip above it
let carScale = 1
const P = 512 // the background's period, in cells
// The background's layers as runs of cells: for each height above the
// horizon (or each row, for the clouds) where its runs start in RUNS and how many.
let RUNS = new Int16Array(1)
let farAt = new Int32Array(1)
let farN = new Int16Array(1)
let nearAt = new Int32Array(1)
let nearN = new Int16Array(1)
let cloudAt = new Int32Array(1)
let cloudN = new Int16Array(1)
let horizon = 1
let sunX = 0
let sunY = 0
let sunR = 0

export const VIEW = new Int16Array(4)

/** The road's view inside the play area (x, y, w, h): a strip for the score on top. */
export function setView(c: Uint8Array, gridCols: number, x: number, y: number, w: number, h: number) {
  buildTrack()
  cells = c
  cols = gridCols
  HY = y
  VX = x
  VY = y + 7
  VW = w
  VH = h - 7
  VIEW[0] = VX
  VIEW[1] = VY
  VIEW[2] = VW
  VIEW[3] = VH
  carScale = Math.max(1, Math.round(VW / 100))
  horizon = VH >> 1
  sunR = Math.max(3, (VH * 0.07) | 0)
  sunX = (VW * 0.72) | 0
  sunY = (horizon * 0.42) | 0
  makeBackground()
}

function makeBackground() {
  // Two ridges as sums of waves around the loop: far mountains, near hills.
  const far = new Uint8Array(P)
  const near = new Uint8Array(P)
  const tall = Math.max(4, (horizon * 0.55) | 0)
  const low = Math.max(2, (horizon * 0.25) | 0)
  for (let x = 0; x < P; x++) {
    const a = (x / P) * Math.PI * 2
    const f = 0.55 + 0.25 * Math.sin(a * 3 + 1) + 0.15 * Math.sin(a * 7 + 2) + 0.08 * Math.sin(a * 17)
    const n = 0.5 + 0.25 * Math.sin(a * 5 + 4) + 0.15 * Math.sin(a * 11) + 0.1 * Math.sin(a * 23 + 1)
    far[x] = Math.max(0, (f * tall) | 0)
    near[x] = Math.max(0, (n * low) | 0)
  }
  const runs: number[] = []
  const layer = (heights: Uint8Array, levels: number, at: Int32Array, count: Int16Array) => {
    for (let d = 0; d < levels; d++) {
      at[d] = runs.length
      let n = 0
      let start = -1
      for (let x = 0; x <= P; x++) {
        const on = x < P && heights[x] > d
        if (on && start < 0) start = x
        if (!on && start >= 0) {
          runs.push(start, x)
          n++
          start = -1
        }
      }
      count[d] = n
    }
  }
  farAt = new Int32Array(horizon + 1)
  farN = new Int16Array(horizon + 1)
  nearAt = new Int32Array(horizon + 1)
  nearN = new Int16Array(horizon + 1)
  layer(far, horizon, farAt, farN)
  layer(near, horizon, nearAt, nearN)
  // Clouds: a few flat puffs high in the sky.
  cloudAt = new Int32Array(horizon + 1)
  cloudN = new Int16Array(horizon + 1)
  const puffs = [40, 4, 18, 150, 9, 26, 260, 3, 22, 360, 7, 30, 450, 12, 16]
  for (let r = 0; r < horizon; r++) {
    cloudAt[r] = runs.length
    let n = 0
    for (let k = 0; k < puffs.length; k += 3) {
      const cx = puffs[k]
      const cy = ((puffs[k + 1] * horizon) / 40) | 0
      const half = ((puffs[k + 2] * VH) / 120) | 0
      const dy = r - cy
      const tall2 = Math.max(1, (half / 5) | 0)
      if (dy < -tall2 || dy > tall2) continue
      const span = (half * Math.sqrt(1 - (dy * dy) / ((tall2 + 1) * (tall2 + 1)))) | 0
      runs.push(cx - span, cx + span)
      n++
    }
    cloudN[r] = n
  }
  RUNS = new Int16Array(runs)
}

// A row of the view: [x0, x1) in view cells, clipped, value v.
function row(y: number, x0: number, x1: number, v: number) {
  if (x0 < 0) x0 = 0
  if (x1 > VW) x1 = VW
  if (x0 >= x1) return
  const base = (VY + y) * cols + VX
  cells.fill(v, base + (x0 | 0), base + (x1 | 0))
}

// Runs of a layer at offset `off`, repeated round the loop.
function runs(y: number, at: number, count: number, off: number, v: number) {
  for (let k = 0; k < count; k++) {
    const a = RUNS[at + 2 * k] - off
    const b = RUNS[at + 2 * k + 1] - off
    for (let rep = -P; rep < VW + P; rep += P) {
      if (b + rep <= 0 || a + rep >= VW) continue
      row(y, a + rep, b + rep, v)
    }
  }
}

let farOff = 0
let nearOff = 0
let cloudOff = 0

function background(top: number) {
  const f = ((farOff % P) + P) % P | 0
  const n = ((nearOff % P) + P) % P | 0
  const c = ((cloudOff % P) + P) % P | 0
  for (let y = 0; y < top; y++) {
    if (y >= horizon) {
      row(y, 0, VW, GROUND)
      continue
    }
    row(y, 0, VW, SKY + ((y * 8) / horizon) | 0)
    const dy = y - sunY
    if (dy >= -sunR && dy <= sunR) {
      const span = SUN_SPAN[(((dy < 0 ? -dy : dy) * 16) / (sunR + 1)) | 0] * sunR
      row(y, sunX - span, sunX + span + 1, SUN)
    }
    if (cloudN[y]) runs(y, cloudAt[y], cloudN[y], c, CLOUD)
    const d = horizon - 1 - y
    if (farN[d]) runs(y, farAt[d], farN[d], f, MOUNT)
    if (nearN[d]) runs(y, nearAt[d], nearN[d], n, HILL)
  }
}

// How wide a circle is at 16ths of its radius from the middle.
const SUN_SPAN = new Float32Array(17)
for (let i = 0; i <= 16; i++) SUN_SPAN[i] = Math.sqrt(Math.max(0, 1 - (i / 16) * (i / 16)))

// --- the race ----------------------------------------------------------------------------

export const S = {
  score: 0,
  lap: 1,
  time: 0,
  speed: 0,
  over: false,
  difficulty: 1,
  traffic: 2,
}
let position = 0
let playerX = 0
let steer = 0 // -1, 0, 1: for the car's lean
let countdown = 0 // steps until the green light
let message = '' // a word in the middle of the view for a moment
let messageFor = 0
let shake = 0
let lastSeg = 0
let distance = 0 // segments driven
let ending = 0
let stepCount = 0
let lapChanged = false

const NC = 16 // traffic
let cars = 0
const carZ = new Float32Array(NC)
const carX = new Float32Array(NC)
const carV = new Float32Array(NC)
const carS = new Uint8Array(NC)
const carAhead = new Int8Array(NC)

const START_TIME = [42, 35, 28]
const BONUS = [19, 15, 12]
const TRAFFIC = [0, 5, 9, 14]

/** A race from the start line. */
export function newRace(difficulty: number, traffic: number) {
  S.score = 0
  S.lap = 1
  S.time = START_TIME[difficulty]
  S.speed = 0
  S.over = false
  S.difficulty = difficulty
  S.traffic = traffic
  position = 0
  playerX = 0
  countdown = 180
  message = ''
  messageFor = 0
  shake = 0
  lastSeg = 0
  distance = 0
  ending = 0
  placeTraffic()
}

/** The title's drive: on its own down the road, nobody racing. */
export function attract() {
  S.speed = MAX_SPEED * 0.62
  S.over = false
  countdown = 0
  playerX = 0
  S.traffic = 2
  placeTraffic()
}

function placeTraffic() {
  cars = TRAFFIC[S.traffic] + (S.lap > 1 ? Math.min(4, S.lap - 1) : 0)
  if (cars > NC) cars = NC
  for (let c = 0; c < cars; c++) {
    carZ[c] = ((position / SEG + 40 + c * (N / (cars + 1)) + rint(30)) % N) * SEG
    carX[c] = (rint(3) - 1) * 0.6
    carV[c] = MAX_SPEED * (0.35 + rfloat() * 0.3)
    carS[c] = rint(3)
    carAhead[c] = 1
  }
}

/** Runs one step: `held` buttons, `gas` true when the car accelerates by
 *  itself, `pointer` -1 / 0 / 1 a finger on the left or the right of the road. */
function tick(held: number, gas: boolean, pointer: number, demo: boolean) {
  stepCount++
  const seg = segOf(position + PLAYER_Z)
  const pct = S.speed / MAX_SPEED
  steer = 0
  if (demo) {
    // Follow the road: lean against the curve.
    playerX += (segCurve[seg] * 0.05 - playerX) * 0.05
  } else if (countdown > 0) {
    countdown--
    if (countdown === 0) {
      message = 'GO!'
      messageFor = 60
    }
  } else {
    const turn = DT * 2.2 * pct
    if (held & LEFT || pointer < 0) {
      playerX -= turn
      steer = -1
    }
    if (held & RIGHT || pointer > 0) {
      playerX += turn
      steer = 1
    }
    // A curve throws the car to the outside.
    playerX -= turn * pct * segCurve[seg] * 0.33
    const accelerate = !S.over && !ending && (held & A || gas) && !(held & B)
    if (held & B) S.speed -= MAX_SPEED * 0.9 * DT
    else if (accelerate) S.speed += (MAX_SPEED / 4.2) * DT * (1.1 - pct * 0.5)
    else S.speed -= (MAX_SPEED / 6) * DT
    // Off the road: grass is slow, and the roadside is hard.
    if ((playerX < -1 || playerX > 1) && S.speed > MAX_SPEED / 3.5) S.speed -= (MAX_SPEED / 1.4) * DT
    if (playerX < -1 || playerX > 1) hitRoadside(seg)
    hitTraffic()
  }
  if (playerX < -2.4) playerX = -2.4
  if (playerX > 2.4) playerX = 2.4
  if (S.speed < 0) S.speed = 0
  if (S.speed > MAX_SPEED) S.speed = MAX_SPEED
  const before = position
  position += S.speed * DT
  // The background turns with the road.
  const ahead = (position - before) / SEG
  farOff += segCurve[seg] * ahead * 1.2
  nearOff += segCurve[seg] * ahead * 2.6
  cloudOff += segCurve[seg] * ahead * 0.5
  if (position >= TRACK) {
    position -= TRACK
    if (!demo) {
      S.lap++
      message = 'LAP ' + S.lap
      messageFor = 120
      lapChanged = true
    }
  }
  moveTraffic()
  if (demo) return
  const now = segOf(position + PLAYER_Z)
  if (now !== lastSeg) {
    const moved = (now - lastSeg + N) % N
    distance += moved
    S.score += moved
    for (let k = 1; k <= moved; k++) {
      const s = (lastSeg + k) % N
      if (segMark[s] && countdown === 0) checkpoint()
    }
    lastSeg = now
  }
  if (countdown === 0 && !ending) {
    S.time -= DT
    if (S.time <= 0) {
      S.time = 0
      ending = 1
      message = 'TIME UP'
      messageFor = 9999
    }
  }
  if (ending && S.speed <= 0.5) {
    if (++ending > 90) S.over = true
  }
  if (messageFor) messageFor--
  if (shake) shake--
}

/** Whether a lap went by since the last call (the time of day moves on). */
export function takeLap(): boolean {
  const was = lapChanged
  lapChanged = false
  return was
}

function checkpoint() {
  const bonus = BONUS[S.difficulty] - (S.lap > 3 ? 2 : 0)
  S.time += bonus
  S.score += 500
  message = 'TIME +' + bonus
  messageFor = 110
}

function segOf(z: number): number {
  const s = (z / SEG) | 0
  return ((s % N) + N) % N
}

function hitRoadside(seg: number) {
  for (let k = 0; k < 2; k++) {
    const kind = k ? sprB[seg] : sprA[seg]
    if (kind < 0) continue
    const x = k ? sprBX[seg] : sprAX[seg]
    const half = KIND_WIDTH[kind] / ROAD_W / 2
    if (playerX + 0.35 > x - half && playerX - 0.35 < x + half) {
      // A tree or a rock: the car stops dead and bounces back to the road.
      S.speed = MAX_SPEED / 6
      playerX += x > playerX ? -0.15 : 0.15
      shake = 20
      return
    }
  }
}

function hitTraffic() {
  const z = position + PLAYER_Z
  for (let c = 0; c < cars; c++) {
    let dz = carZ[c] - z
    if (dz < -TRACK / 2) dz += TRACK
    if (dz > TRACK / 2) dz -= TRACK
    const ahead = dz > 0 ? 1 : -1
    if (carAhead[c] > 0 && ahead < 0 && S.speed > carV[c] && countdown === 0) {
      S.score += 50 // overtaken
    }
    carAhead[c] = ahead
    if (dz > 0 && dz < SEG * 1.2 && S.speed > carV[c] && playerX + 0.32 > carX[c] - 0.32 && playerX - 0.32 < carX[c] + 0.32) {
      // Into its back: down to its speed and a little behind it.
      S.speed = carV[c] * 0.7
      position = carZ[c] - PLAYER_Z - SEG * 1.3
      if (position < 0) position += TRACK
      shake = 14
    }
  }
}

function moveTraffic() {
  for (let c = 0; c < cars; c++) {
    carZ[c] += carV[c] * DT
    if (carZ[c] >= TRACK) carZ[c] -= TRACK
  }
}

// --- drawing -----------------------------------------------------------------------------

// Per segment drawn this frame (by its distance n ahead): where its near end
// is on screen, its scale, and the row nearer road was drawn down to.
const pX = new Float32Array(DRAW + 1)
const pY = new Float32Array(DRAW + 1)
const pW = new Float32Array(DRAW + 1)
const pS = new Float32Array(DRAW + 1)
const pClip = new Float32Array(DRAW + 1)
const pOn = new Uint8Array(DRAW + 1)
const carHead = new Int8Array(DRAW)
const carNext = new Int8Array(NC)

/** Runs the steps and draws the view. */
export function frame(steps: number, held: number, gas: boolean, pointer: number, demo: boolean) {
  for (let i = 0; i < steps; i++) tick(held, gas, pointer, demo)
  draw(demo)
}

function draw(demo: boolean) {
  clip(VX, VY, VW, VH)
  const halfW = VW / 2
  const halfH = VH / 2
  const base = segOf(position)
  const basePct = (position % SEG) / SEG
  const ps = segOf(position + PLAYER_Z)
  const pPct = ((position + PLAYER_Z) % SEG) / SEG
  const camY = segY[ps] + (segY[ps + 1] - segY[ps]) * pPct + CAM_H
  const camX = playerX * ROAD_W
  let maxY = VH
  let x = 0
  let dx = -(segCurve[base] * basePct)
  for (let n = 0; n < DRAW; n++) {
    const i = (base + n) % N
    const camZ = i < base ? position - TRACK : position
    const z1 = i * SEG - camZ
    const z2 = z1 + SEG
    pOn[n] = 0
    pClip[n] = maxY
    if (z1 <= DEPTH * 2) {
      x += dx
      dx += segCurve[i]
      continue
    }
    const s1 = DEPTH / z1
    const s2 = DEPTH / z2
    const x1 = halfW + s1 * (x - camX) * halfW
    const y1 = halfH - s1 * (segY[i] - camY) * halfH
    const w1 = s1 * ROAD_W * halfW
    const x2 = halfW + s2 * (x + dx - camX) * halfW
    const y2 = halfH - s2 * (segY[i + 1] - camY) * halfH
    const w2 = s2 * ROAD_W * halfW
    x += dx
    dx += segCurve[i]
    pX[n] = x1
    pY[n] = y1
    pW[n] = w1
    pS[n] = s1
    pOn[n] = 1
    if (y2 >= y1 || y2 >= maxY) continue
    segment(i, x1, y1, w1, x2, y2, w2, maxY)
    maxY = y2
  }
  background(maxY > 0 ? (maxY + 0.999) | 0 : 0)
  // The traffic, sorted into the segments it is in.
  carHead.fill(-1)
  for (let c = 0; c < cars; c++) {
    const n = (segOf(carZ[c]) - base + N) % N
    if (n >= DRAW) continue
    carNext[c] = carHead[n]
    carHead[n] = c
  }
  for (let n = DRAW - 1; n >= 0; n--) {
    if (!pOn[n]) continue
    const i = (base + n) % N
    const s = pS[n]
    const clipY = pClip[n]
    if (sprA[i] >= 0) thing(sprA[i], pX[n] + s * sprAX[i] * ROAD_W * halfW, pY[n], s * halfW, clipY)
    if (sprB[i] >= 0) thing(sprB[i], pX[n] + s * sprBX[i] * ROAD_W * halfW, pY[n], s * halfW, clipY)
    if (segMark[i]) arch(pX[n], pY[n], pW[n], clipY, segMark[i])
    for (let c = carHead[n]; c >= 0; c = carNext[c]) {
      const spr = CARS[carS[c]]
      const w = s * 620 * halfW
      scaled(spr, pX[n] + s * carX[c] * ROAD_W * halfW, pY[n], w, (w * spr.h) / spr.w, clipY)
    }
  }
  // The player's car.
  const car = steer < 0 ? PLAYER_LEFT : steer > 0 ? PLAYER_RIGHT : PLAYER_S
  const cw = car.w * carScale
  const ch = car.h * carScale
  const bump = (playerX < -1 || playerX > 1) && S.speed > 50 ? (stepCount >> 2) & 1 : 0
  const jolt = shake ? ((shake >> 1) & 1 ? 1 : -1) : 0
  scaled(car, halfW + jolt, VH - 1 - bump, cw, ch, VH)
  if (bump) {
    // Dust off the wheels on the grass.
    for (let k = 0; k < 4; k++) {
      const at = halfW - (cw >> 1) - 2 + rint(cw + 4)
      row(VH - 1 - rint(3), at, at + 1, DUST)
    }
  }
  if (!demo) overlay()
}

/** One segment of road between its near end (x1, y1, half width w1) and its
 *  far end, a row at a time, below `maxY` only. */
function segment(i: number, x1: number, y1: number, w1: number, x2: number, y2: number, w2: number, maxY: number) {
  const light = ((i / 3) | 0) & 1
  const grass = light ? GRASS_L : GRASS_D
  const rumble = light ? RUMBLE_L : RUMBLE_D
  const road = light ? ROAD_L : ROAD_D
  let top = (y2 + 0.5) | 0
  let bottom = (y1 + 0.5) | 0
  if (top < 0) top = 0
  if (bottom > maxY) bottom = (maxY + 0.5) | 0
  if (bottom > VH) bottom = VH
  const span = y1 - y2
  for (let y = top; y < bottom; y++) {
    const t = (y1 - y) / span
    const xc = x1 + (x2 - x1) * t
    const w = w1 + (w2 - w1) * t
    const r = w / 6
    const a = (xc - w) | 0
    const b = (xc + w) | 0
    const base = (VY + y) * cols + VX
    // Grass across the row, then the road over it.
    cells.fill(grass, base, base + VW)
    row(y, a - r, b + r, rumble)
    row(y, a, b, road)
    if (light && w > 10) {
      const lane = w > 40 ? 2 : 1
      const third = (2 * w) / 3
      row(y, a + third - (lane >> 1), a + third - (lane >> 1) + lane, LANE)
      row(y, b - third - (lane >> 1), b - third - (lane >> 1) + lane, LANE)
    }
  }
}

/** A roadside thing standing at (x, bottom), `unit` the scale of a world unit. */
function thing(kind: number, x: number, bottom: number, unit: number, clipY: number) {
  const spr = KIND_SPRITES[kind]
  const w = KIND_WIDTH[kind] * unit
  if (w < 1) return
  scaled(spr, x, bottom, w, (w * spr.h) / spr.w, clipY)
}

/** The start line or a checkpoint: two posts and a banner over the road. */
function arch(x: number, bottom: number, w: number, clipY: number, kind: number) {
  if (w < 3) return
  const postW = Math.max(1, w * 0.06)
  const h = w * 0.9
  const left = x - w * 1.15
  const right = x + w * 1.15
  const lim = clipY < VH ? clipY : VH
  clip(VX, VY, VW, Math.max(0, lim | 0))
  fill(VX + left - postW, VY + bottom - h, postW, h, POST)
  fill(VX + right, VY + bottom - h, postW, h, POST)
  const bh = Math.max(2, w * 0.22)
  const top = bottom - h
  fill(VX + left - postW, VY + top, right - left + 2 * postW, bh, BANNER)
  // A checked edge, then the word if it fits.
  const sq = Math.max(1, (bh / 4) | 0)
  for (let cx = left - postW, k = 0; cx < right + postW; cx += sq, k++) {
    fill(VX + cx, VY + top + (k & 1 ? 0 : bh - sq), sq, sq, BANNER_2)
  }
  const word = kind === 1 ? 'LAP' : 'CHECK'
  const sc = Math.max(1, Math.min(4, ((bh - 2 * sq) / 6) | 0))
  if (textWidth(word, sc) < right - left - 2 && bh - 2 * sq >= 5) {
    textCenter(word, VX + x, VY + top + ((bh - 5 * sc) >> 1), sc, BANNER_2)
  }
  clip(VX, VY, VW, VH)
}

/**
 * A sprite drawn `w` x `h` cells with its bottom middle at (x, bottom), in
 * view cells, nothing at or below `clipY` (a hill's crest in front of it).
 * Each source cell is one run a row: a near tree is a few fills a row.
 */
function scaled(spr: any, x: number, bottom: number, w: number, h: number, clipY: number) {
  if (w < 1 || h < 1) return
  const sw = spr.w
  const sh = spr.h
  const d = spr.d
  const x0 = x - w / 2
  const y0 = bottom - h
  let top = y0 < 0 ? 0 : (y0 + 0.5) | 0
  let end = (bottom + 0.5) | 0
  const lim = clipY < VH ? (clipY + 0.5) | 0 : VH
  if (end > lim) end = lim
  if (top >= end) return
  const step = w / sw
  for (let y = top; y < end; y++) {
    let sy = (((y - y0) * sh) / h) | 0
    if (sy >= sh) sy = sh - 1
    const src = sy * sw
    const base = (VY + y) * cols + VX
    for (let sx = 0; sx < sw; sx++) {
      const v = d[src + sx]
      if (v === 255) continue
      let a = (x0 + sx * step + 0.5) | 0
      let b = (x0 + (sx + 1) * step + 0.5) | 0
      if (a < 0) a = 0
      if (b > VW) b = VW
      if (a < b) cells.fill(v, base + a, base + b)
    }
  }
}

/** What the driver needs over the road: time, speed and gear, the countdown, a word. */
function overlay() {
  const big = Math.max(2, Math.min(3, (VW / 45) | 0))
  const t = Math.ceil(S.time)
  const warn = t <= 10 && (stepCount >> 4) & 1
  const tw = (t >= 10 ? 7 : 3) * big
  number(t, VX + ((VW - tw) >> 1) + 1, VY + 3, big, UI_SHADOW)
  number(t, VX + ((VW - tw) >> 1), VY + 2, big, warn ? WARN : TIME)
  // Speed and gear in the bottom corners, beside the car.
  const kmh = ((S.speed / MAX_SPEED) * 260) | 0
  const gear = S.speed < 1 ? 0 : 1 + Math.min(4, ((S.speed / MAX_SPEED) * 5) | 0)
  const y = VY + VH - 7
  // On small dark plates, so they read over grass and road alike.
  fill(VX + 1, y - 1, 26, 7, HUD)
  fill(VX + VW - 12, y - 1, 11, 7, HUD)
  const wn = number(kmh, VX + 2, y, 1, HUD_TEXT, 3)
  text('KMH', VX + 3 + wn, y, 1, HUD_DIM)
  text('G', VX + VW - 10, y, 1, HUD_DIM)
  if (gear) number(gear, VX + VW - 6, y, 1, HUD_TEXT)
  else text('N', VX + VW - 6, y, 1, HUD_TEXT)
  let word = message
  if (countdown > 0) word = countdown > 120 ? '3' : countdown > 60 ? '2' : '1'
  if (word && (messageFor || countdown > 0)) {
    const sc = Math.max(1, Math.min(4, Math.floor((VW - 4) / (word.length * 4))))
    title(word, VX + (VW >> 1), VY + ((VH * 0.3) | 0), sc, UI_TITLE, UI_SHADOW)
  }
}

// --- the score strip ------------------------------------------------------------------------

let shownScore = -1
let shownLap = -1
let best = 0

export function setBest(n: number) {
  best = n
}

/** Score, lap and best above the view, drawn again when they change. */
export function drawHud(force: boolean, playing: boolean) {
  if (!force && shownScore === S.score && shownLap === S.lap) return
  shownScore = S.score
  shownLap = S.lap
  clip(VX, HY, VW, 7)
  fill(VX, HY, VW, 7, HUD)
  if (playing) {
    number(S.score, VX + 1, HY + 1, 1, HUD_TEXT, 6)
    const lapW = textWidth('LAP 0', 1)
    text('LAP', VX + VW - lapW - 1, HY + 1, 1, HUD_DIM)
    number(S.lap, VX + VW - 4, HY + 1, 1, HUD_TEXT)
  } else {
    text('HI', VX + 1, HY + 1, 1, HUD_DIM)
    number(best, VX + 13, HY + 1, 1, HUD_TEXT, 6)
  }
  clip(VX, VY, VW, VH)
}

/** The race's place, to come back to after the interpreter was dropped. */
export function snapshot() {
  return { score: S.score, lap: S.lap, time: S.time, position, playerX, distance }
}

export function resume(snap: any, difficulty: number, traffic: number) {
  newRace(difficulty, traffic)
  S.score = snap.score | 0
  S.lap = snap.lap | 0 || 1
  S.time = Math.max(5, +snap.time || 0)
  position = +snap.position || 0
  playerX = +snap.playerX || 0
  distance = snap.distance | 0
  lastSeg = segOf(position + PLAYER_Z)
  countdown = 0
  placeTraffic()
}

sources.gfx.ts:
// Drawing into the cells of the 8-bit palette mode: a byte a cell, an index
// into the game's palette. Everything here draws into one target, set with
// target() when the cells are made; every shape is clipped to it. Rows are
// filled with Uint8Array.fill, which is one native memset a run: far cheaper
// than a loop of cell writes in QuickJS.

let C: Uint8Array = new Uint8Array(1)
let CW = 1 // the grid's width: a row's stride
// The clip box: nothing is drawn outside [X0, X1) x [Y0, Y1).
let X0 = 0
let Y0 = 0
let X1 = 1
let Y1 = 1

/** The cells everything draws into: a grid `w` cells wide and `h` high,
 *  clipped to all of it. */
export function target(cells: Uint8Array, w: number, h: number) {
  C = cells
  CW = w
  X0 = 0
  Y0 = 0
  X1 = w
  Y1 = h
}

/** Draw only inside this rectangle (a play area under a score strip). */
export function clip(x: number, y: number, w: number, h: number) {
  X0 = x
  Y0 = y
  X1 = x + w
  Y1 = y + h
}

/** A filled rectangle. */
export function fill(x: number, y: number, w: number, h: number, v: number) {
  let x0 = x | 0
  let x1 = (x + w) | 0
  let y0 = y | 0
  let y1 = (y + h) | 0
  if (x0 < X0) x0 = X0
  if (y0 < Y0) y0 = Y0
  if (x1 > X1) x1 = X1
  if (y1 > Y1) y1 = Y1
  if (x0 >= x1) return
  for (let r = y0; r < y1; r++) C.fill(v, r * CW + x0, r * CW + x1)
}

/** One cell. */
export function put(x: number, y: number, v: number) {
  if (x >= X0 && y >= Y0 && x < X1 && y < Y1) C[(y | 0) * CW + (x | 0)] = v
}

/** A button-ish box: a face with a border and its corners cut off (left as
 *  `under`, what the box sits on). */
export function box(x: number, y: number, w: number, h: number, face: number, border: number, under: number) {
  fill(x, y, w, h, border)
  fill(x + 1, y + 1, w - 2, h - 2, face)
  put(x, y, under)
  put(x + w - 1, y, under)
  put(x, y + h - 1, under)
  put(x + w - 1, y + h - 1, under)
}

/** Copies a rectangle from `layer` (cells of the same grid) back into the
 *  target: what a moving thing covered, put back. */
export function restore(layer: Uint8Array, x: number, y: number, w: number, h: number) {
  let x0 = x | 0
  let x1 = (x + w) | 0
  let y0 = y | 0
  let y1 = (y + h) | 0
  if (x0 < X0) x0 = X0
  if (y0 < Y0) y0 = Y0
  if (x1 > X1) x1 = X1
  if (y1 > Y1) y1 = Y1
  for (let r = y0; r < y1; r++) {
    const row = r * CW
    for (let i = row + x0; i < row + x1; i++) C[i] = layer[i]
  }
}

// --- sprites ---------------------------------------------------------------

/** A sprite: `w` x `h` palette indexes, 255 where it is see-through. */
export type Sprite = { w: number; h: number; d: Uint8Array }

/**
 * A sprite from a compact string: rows split by `|`, a character a cell, `.`
 * see-through, and every other character the palette index at its place in
 * `values` for its place in `keys` ("ab", [12, 13]: a is 12, b is 13).
 */
export function sprite(text: string, keys: string, values: number[]): Sprite {
  const lines = text.split('|')
  const h = lines.length
  let w = 0
  for (const line of lines) if (line.length > w) w = line.length
  const d = new Uint8Array(w * h).fill(255)
  for (let y = 0; y < h; y++) {
    const line = lines[y]
    for (let x = 0; x < line.length; x++) {
      const k = keys.indexOf(line[x])
      if (k >= 0) d[y * w + x] = values[k]
    }
  }
  return { w, h, d }
}

/** Draws a sprite with its top left at (x, y). `tint` (when not 255) paints
 *  every solid cell that one index: a flash when something is hit. */
export function blit(s: Sprite, x: number, y: number, tint = 255) {
  const sw = s.w
  const d = s.d
  x = x | 0
  y = y | 0
  let sx0 = 0
  let sy0 = 0
  let sx1 = sw
  let sy1 = s.h
  if (x < X0) sx0 = X0 - x
  if (y < Y0) sy0 = Y0 - y
  if (x + sx1 > X1) sx1 = X1 - x
  if (y + sy1 > Y1) sy1 = Y1 - y
  for (let sy = sy0; sy < sy1; sy++) {
    const src = sy * sw
    const dst = (y + sy) * CW + x
    for (let sx = sx0; sx < sx1; sx++) {
      const v = d[src + sx]
      if (v !== 255) C[dst + sx] = tint === 255 ? v : tint
    }
  }
}

/** Puts back what a sprite at (x, y) covered: only its solid cells, from `layer`. */
export function unblit(s: Sprite, x: number, y: number, layer: Uint8Array) {
  const sw = s.w
  const d = s.d
  x = x | 0
  y = y | 0
  let sx0 = 0
  let sy0 = 0
  let sx1 = sw
  let sy1 = s.h
  if (x < X0) sx0 = X0 - x
  if (y < Y0) sy0 = Y0 - y
  if (x + sx1 > X1) sx1 = X1 - x
  if (y + sy1 > Y1) sy1 = Y1 - y
  for (let sy = sy0; sy < sy1; sy++) {
    const src = sy * sw
    const dst = (y + sy) * CW + x
    for (let sx = sx0; sx < sx1; sx++) {
      if (d[src + sx] !== 255) C[dst + sx] = layer[dst + sx]
    }
  }
}

// --- text ------------------------------------------------------------------

// A 3x5 font, 15 bits a glyph, the top row first and each row's left dot its
// high bit. Letters, digits and a little punctuation; `@` is a heart.
const GLYPHS: Record<string, number> = {
  A: 0x2bed, B: 0x6bae, C: 0x3923, D: 0x6b6e, E: 0x79a7, F: 0x79a4, G: 0x396b, H: 0x5bed, I: 0x7497,
  J: 0x126a, K: 0x5bad, L: 0x4927, M: 0x5fed, N: 0x6b6d, O: 0x2b6a, P: 0x6ba4, Q: 0x2b73, R: 0x6bad,
  S: 0x388e, T: 0x7492, U: 0x5b6f, V: 0x5b6a, W: 0x5bfd, X: 0x5aad, Y: 0x5a92, Z: 0x72a7,
  0: 0x7b6f, 1: 0x2c97, 2: 0x73e7, 3: 0x73cf, 4: 0x5bc9, 5: 0x79cf, 6: 0x79ef, 7: 0x7249, 8: 0x7bef, 9: 0x7bcf,
  '-': 0x01c0, '+': 0x05d0, '<': 0x1511, '>': 0x4454, '.': 0x0002, ':': 0x0410, '/': 0x12a4, ' ': 0,
  '!': 0x2482, '?': 0x7282, "'": 0x2400, ',': 0x0014, '%': 0x52a5, '#': 0x5f7d, '*': 0x0aa8, '=': 0x0e38,
  '(': 0x2922, ')': 0x224a, '@': 0x5fd0, '_': 0x0007,
}

/** A character's 15 dots (0 for one the font lacks). */
export function glyphBits(ch: string): number {
  return GLYPHS[ch] ?? GLYPHS[ch.toUpperCase()] ?? 0
}

/** Cells a line of text takes at `scale`: 4 dots a letter, less the last gap. */
export function textWidth(text: string, scale: number): number {
  return text.length ? (text.length * 4 - 1) * scale : 0
}

/**
 * Text with its top left at (x, y), `scale` cells a dot. With `ramp` each row
 * of dots is one index further from `v` (v, v+1, ... v+4: a gradient down the
 * letters); with `upside` it is turned 180 degrees, for the player across the
 * table.
 */
export function text(s: string, x: number, y: number, scale: number, v: number, ramp = false, upside = false) {
  const n = s.length
  for (let g = 0; g < n; g++) {
    const ch = s[upside ? n - 1 - g : g]
    const bits = glyphBits(ch)
    if (!bits) continue
    const left = x + g * 4 * scale
    for (let i = 0; i < 15; i++) {
      const bit = upside ? i : 14 - i
      if (!(bits & (1 << bit))) continue
      const dotRow = (i / 3) | 0
      fill(left + (i % 3) * scale, y + dotRow * scale, scale, scale, ramp ? v + (upside ? 4 - dotRow : dotRow) : v)
    }
  }
}

/** Text centred on column `cx`. */
export function textCenter(s: string, cx: number, y: number, scale: number, v: number, ramp = false) {
  text(s, cx - ((textWidth(s, scale) / 2) | 0), y, scale, v, ramp)
}

/** A headline: gradient letters (`v` .. `v`+4) over a drop shadow `shadow`. */
export function title(s: string, cx: number, y: number, scale: number, v: number, shadow: number) {
  const x = cx - ((textWidth(s, scale) / 2) | 0)
  const off = scale > 1 ? (scale / 2) | 0 : 1
  text(s, x + off, y + off, scale, shadow)
  text(s, x, y, scale, v, true)
}

// The digits' glyphs, for numbers drawn every frame without making a string.
const DIGITS = new Int32Array(10)
for (let d = 0; d < 10; d++) DIGITS[d] = GLYPHS[String(d)]

/** A whole number at (x, y), at least `width` digits (zeros in front), with
 *  no string made: a speed or a clock drawn every frame. Answers its width. */
export function number(n: number, x: number, y: number, scale: number, v: number, width = 1): number {
  n = n < 0 ? 0 : n | 0
  let count = 1
  for (let k = n; k >= 10; k = (k / 10) | 0) count++
  if (count < width) count = width
  let at = x + (count - 1) * 4 * scale
  for (let i = 0; i < count; i++) {
    const bits = DIGITS[n % 10]
    for (let b = 0; b < 15; b++) {
      if (bits & (1 << (14 - b))) fill(at + (b % 3) * scale, y + ((b / 3) | 0) * scale, scale, scale, v)
    }
    n = (n / 10) | 0
    at -= 4 * scale
  }
  return count * 4 * scale - scale
}

sources.input.ts:
// Input for the games: touch (each finger by its pointerId, so one can hold
// left while another fires), GPIO buttons (down and up the moment they
// happen) and a keyboard, all folded into one set of action bits. What is
// held is held(); a press that came and went between two frames still counts
// once through take(), so a quick tap of a GPIO key is never lost.

export const LEFT = 1
export const RIGHT = 2
export const UP = 4
export const DOWN = 8
export const A = 16
export const B = 32
export const START = 64 // pause / resume / start
export const TAP = 128 // a finger or a click on the play area (not a control)

const ACTIONS: Record<string, number> = {
  left: LEFT, right: RIGHT, up: UP, down: DOWN, a: A, fire: A, b: B, bomb: B, brake: B,
  start: START, pause: START, gas: A, jump: A, button: A,
}

const MAX = 32 // pointer ids are folded into this many slots
const ptrBits = new Uint8Array(MAX)
const ptrDrag = new Uint8Array(MAX)
/** Which pointers are down on the play area (not on a control), by id. */
export const drags = ptrDrag
/** Where each dragging pointer is now and where it went down, in scene pixels. */
export const ptrX = new Int16Array(MAX)
export const ptrY = new Int16Array(MAX)
export const ptrStartX = new Int16Array(MAX)
export const ptrStartY = new Int16Array(MAX)
const pinBits = new Uint8Array(64)
let keyBits = 0
let gpioBits = 0
let latched = 0
let gpioSeen = false
let labels: Record<string, number> = {}
let hitTest: (x: number, y: number) => number = () => 0
// What was used last: 'touch', 'key' or 'gpio'.
let lastKind = ''
let tapX = 0
let tapY = 0

/** How a pointer at (x, y) scene pixels hits the on-screen controls: their
 *  action bits, or 0 for the play area (a drag there). */
export function setHitTest(fn: (x: number, y: number) => number) {
  hitTest = fn
}

/** The "Buttons" setting: `LEFT=left, RIGHT=right, KEY1=a`. Labels (and
 *  roles) are matched without case; a key it does not name is A. */
export function setButtons(spec: string) {
  labels = {}
  for (const part of String(spec || '').split(',')) {
    const eq = part.indexOf('=')
    if (eq < 0) continue
    const name = part.slice(0, eq).trim().toLowerCase()
    const action = ACTIONS[part.slice(eq + 1).trim().toLowerCase()]
    if (name && action) labels[name] = action
  }
}

function gpioAction(payload: any): number {
  const label = String(payload.label || '').toLowerCase()
  const role = String(payload.role || '').toLowerCase()
  return labels[label] || labels[role] || ACTIONS[label] || A
}

/** The default keys: arrows and WASD, Space / Z / J for A, X / K / C for B,
 *  Enter, P and Escape to pause. */
export function keyAction(code: string): number {
  switch (code) {
    case 'ArrowLeft': case 'KeyA': return LEFT
    case 'ArrowRight': case 'KeyD': return RIGHT
    case 'ArrowUp': case 'KeyW': return UP
    case 'ArrowDown': case 'KeyS': return DOWN
    case 'Space': case 'KeyZ': case 'KeyJ': return A
    case 'KeyX': case 'KeyK': case 'KeyC': return B
    case 'Enter': case 'NumpadEnter': case 'KeyP': case 'Escape': return START
  }
  return 0
}

function recount() {
  let g = 0
  for (let i = 0; i < 64; i++) g |= pinBits[i]
  gpioBits = g
}

/**
 * One input event. Answers the action bits it pressed (0 when it pressed
 * nothing, -1 when it was not input at all), so a game can react at once.
 * `keys` maps a key code to bits (keyAction by default).
 */
export function handle(event: string, p: any, keys: (code: string) => number = keyAction): number {
  if (event === 'pointerDown' || event === 'pointerMove') {
    const id = (p.pointerId | 0) & (MAX - 1)
    const x = p.x | 0
    const y = p.y | 0
    if (event === 'pointerMove' && !ptrBits[id] && !ptrDrag[id]) return 0 // a mouse passing over
    lastKind = 'touch'
    if (event === 'pointerDown') {
      const bits = hitTest(x, y)
      ptrBits[id] = bits
      ptrDrag[id] = bits ? 0 : 1
      ptrX[id] = ptrStartX[id] = x
      ptrY[id] = ptrStartY[id] = y
      tapX = x
      tapY = y
      latched |= bits || TAP
      return bits || TAP
    }
    ptrX[id] = x
    ptrY[id] = y
    if (ptrBits[id]) {
      // A thumb sliding from one button to the next presses that one.
      const bits = hitTest(x, y)
      const fresh = bits & ~ptrBits[id]
      ptrBits[id] = bits
      latched |= fresh
      return fresh
    }
    return 0
  }
  if (event === 'pointerUp' || event === 'pointerCancel') {
    const id = (p.pointerId | 0) & (MAX - 1)
    ptrBits[id] = 0
    ptrDrag[id] = 0
    return 0
  }
  if (event === 'keyDown' || event === 'keyUp') {
    const bits = keys(String(p.code || p.key || ''))
    if (!bits) return 0
    lastKind = 'key'
    if (event === 'keyUp') {
      keyBits &= ~bits
      return 0
    }
    if (p.repeat) return 0
    keyBits |= bits
    latched |= bits
    return bits
  }
  if (event === 'gpio') {
    gpioSeen = true
    lastKind = 'gpio'
    const pin = (p.pin | 0) & 63
    if (p.action === 'down') {
      const bits = gpioAction(p)
      pinBits[pin] = bits
      latched |= bits
      recount()
      return bits
    }
    if (p.action === 'up') {
      pinBits[pin] = 0
      recount()
    }
    return 0
  }
  if (event === 'button') {
    // Only where no gpio edges arrive: a press after the release.
    if (gpioSeen || (p.action !== 'press' && p.action !== 'doublePress')) return 0
    lastKind = 'gpio'
    const bits = gpioAction(p)
    latched |= bits
    return bits
  }
  return -1
}

/** Everything held now. */
export function held(): number {
  let bits = keyBits | gpioBits
  for (let i = 0; i < MAX; i++) bits |= ptrBits[i]
  return bits
}

/** Counts as a press of `bits` (a swipe in from an edge that means pause). */
export function press(bits: number) {
  latched |= bits
}

/** The presses since the last call. */
export function take(): number {
  const bits = latched
  latched = 0
  return bits
}

/** The id of a finger dragging on the play area, or -1. */
export function dragging(): number {
  for (let i = 0; i < MAX; i++) if (ptrDrag[i]) return i
  return -1
}

/** Where the last finger or click went down, in scene pixels. */
export function lastTapX(): number {
  return tapX
}
export function lastTapY(): number {
  return tapY
}

/** Every finger lets go (a pause, the scene closing). */
export function releaseAll() {
  ptrBits.fill(0)
  ptrDrag.fill(0)
  pinBits.fill(0)
  keyBits = 0
  gpioBits = 0
  latched = 0
}

/** Whether a keyboard was the last thing used. */
export function usingKeyboard(): boolean {
  return lastKind === 'key'
}

sources.controls.ts:
// The on-screen controls: a D-pad (left/right, or a cross) and up to two
// action buttons, drawn into the cells, with a pause button. On a wide screen
// they sit in panels at both sides (thumbs on a held tablet); on a square or
// tall one in a bar along the bottom. Buttons are at least ~60 px on the
// glass and ~24 px from the screen's edges, where a swipe belongs to the
// frame. The palette indexes they draw with are the kit's UI slots (ui.ts).
import { box, fill, text, textCenter, textWidth } from './gfx'
import { A, B, DOWN, LEFT, RIGHT, START, UP } from './input'
import { UI_BORDER, UI_EDGE, UI_FACE, UI_ICON, UI_ICON_LIT, UI_LIT, UI_PANEL } from './ui'

const ICON_LEFT = 1
const ICON_RIGHT = 2
const ICON_UP = 3
const ICON_DOWN = 4
const ICON_A = 5
const ICON_B = 6
const ICON_PAUSE = 7

export type Layout = {
  /** The play area, in cells. */
  x: number
  y: number
  w: number
  h: number
  wide: boolean
  /** Buttons: 5 numbers each (bits, x, y, w, h) and an icon. */
  n: number
  b: Int16Array
  icon: Uint8Array
  /** Panels behind the buttons: x, y, w, h each. */
  np: number
  panels: Int16Array
  /** The D-pad's box, which picks a direction by where in it a finger is. */
  dx: number
  dy: number
  dw: number
  dh: number
  dpad: number
  gap: number
  px: number
  labelA: string
  labelB: string
  /** A round panel's: the game's name in the arc above the play area, at (nameX, nameY). */
  name?: string
  nameX?: number
  nameY?: number
}

/**
 * Where everything goes on a `cols` x `rows` grid of `px`-pixel cells.
 * `dpad` 0 (none), 2 (left and right) or 4 (a cross); `actions` 0, 1 (A) or
 * 2 (A and B); `show` false leaves the whole screen to the game. `sides`
 * false keeps the bar along the bottom on a wide screen too (a wide view).
 */
export function layout(cols: number, rows: number, px: number, dpad: number, actions: number, show: boolean,
    labelA = 'A', labelB = 'B', sides = true): Layout {
  const L: Layout = {
    x: 0, y: 0, w: cols, h: rows, wide: sides && cols >= rows * 1.25, n: 0, b: new Int16Array(40), icon: new Uint8Array(8),
    np: 0, panels: new Int16Array(8), dx: 0, dy: 0, dw: 0, dh: 0, dpad, gap: 1, px, labelA, labelB,
  }
  if (!show) return L
  let bs = Math.max(8, Math.ceil(60 / px)) // a button, in cells
  const edge = Math.max(2, Math.ceil(24 / px)) // kept free along the screen's edges
  const gap = Math.max(1, Math.round(bs / 6))
  L.gap = gap
  if (dpad === 4) bs = Math.max(7, Math.min(bs, Math.floor((rows - 2 * edge) / 3.6)))
  const padW = dpad === 4 ? 3 * bs : dpad === 2 ? 2 * bs + gap : 0
  const padH = dpad === 4 ? 3 * bs : dpad === 2 ? bs : 0
  const actW = actions === 2 ? 2 * bs + gap : actions === 1 ? bs : 0
  const actH = actions === 2 ? bs + (bs >> 1) : actions === 1 ? bs : 0
  const ps = Math.max(6, Math.round(bs * 0.65)) // the pause button
  const add = (bits: number, x: number, y: number, w: number, h: number, icon: number) => {
    const at = L.n * 5
    L.b[at] = bits
    L.b[at + 1] = x
    L.b[at + 2] = y
    L.b[at + 3] = w
    L.b[at + 4] = h
    L.icon[L.n] = icon
    L.n++
  }
  const panel = (x: number, y: number, w: number, h: number) => {
    L.panels.set([x, y, w, h], L.np * 4)
    L.np++
  }
  let padX = 0
  let padY = 0
  let actX = 0
  let actY = 0
  if (L.wide) {
    const side = Math.max(padW, actW, ps) + edge + 2 * gap
    L.x = side
    L.w = cols - 2 * side
    panel(0, 0, side, rows)
    panel(cols - side, 0, side, rows)
    // The thumbs' places: a little below the middle.
    padX = edge
    padY = Math.min(rows - edge - padH, Math.round(rows * 0.58 - padH / 2))
    actX = cols - edge - actW
    actY = Math.min(rows - edge - actH, Math.round(rows * 0.58 - actH / 2))
    add(START, cols - edge - ps, edge, ps, ps, ICON_PAUSE)
  } else {
    const content = Math.max(padH, actH, ps)
    const bar = content + edge + 2 * gap
    L.h = rows - bar
    panel(0, rows - bar, cols, bar)
    padX = edge
    padY = rows - edge - gap - content + ((content - padH) >> 1)
    actX = cols - edge - actW
    actY = rows - edge - gap - content + ((content - actH) >> 1)
    add(START, (cols - ps) >> 1, rows - edge - gap - content + ((content - ps) >> 1), ps, ps, ICON_PAUSE)
  }
  if (dpad === 2) {
    add(LEFT, padX, padY, bs, bs, ICON_LEFT)
    add(RIGHT, padX + bs + gap, padY, bs, bs, ICON_RIGHT)
  } else if (dpad === 4) {
    add(UP, padX + bs, padY, bs, bs, ICON_UP)
    add(LEFT, padX, padY + bs, bs, bs, ICON_LEFT)
    add(RIGHT, padX + 2 * bs, padY + bs, bs, bs, ICON_RIGHT)
    add(DOWN, padX + bs, padY + 2 * bs, bs, bs, ICON_DOWN)
  }
  L.dx = padX
  L.dy = padY
  L.dw = padW
  L.dh = padH
  if (actions === 2) {
    // B up and to the left, A down and to the right, as on a game pad.
    add(B, actX, actY, bs, bs, ICON_B)
    add(A, actX + bs + gap, actY + (bs >> 1), bs, bs, ICON_A)
  } else if (actions === 1) {
    add(A, actX, actY, bs, bs, ICON_A)
  }
  return L
}

/**
 * The same for a round panel (context.round), where only the circle inside the
 * square shows: the buttons follow the rim along the bottom (the D-pad on the
 * left, the actions on the right, the pause button in the middle), and the
 * play area is the biggest rectangle inside the circle above them (`square`
 * asks for one about as tall as wide). `name` goes in the arc above it.
 */
export function roundLayout(cols: number, rows: number, px: number, dpad: number, actions: number, show: boolean,
    labelA = 'A', labelB = 'B', square = false, name = ''): Layout {
  const L = layout(cols, rows, px, 0, 0, false, labelA, labelB, false)
  L.dpad = show ? dpad : 0
  const cx = cols / 2
  const cy = rows / 2
  const r = Math.min(cols, rows) / 2 - Math.ceil(12 / px) // kept in from the rim
  const bs = Math.max(8, Math.ceil(56 / px))
  const gap = Math.max(1, Math.round(bs / 6))
  const ps = Math.max(6, Math.round(bs * 0.65))
  L.gap = gap
  const add = (bits: number, x: number, y: number, w: number, h: number, icon: number) => {
    const at = L.n * 5
    L.b[at] = bits
    L.b[at + 1] = Math.round(x)
    L.b[at + 2] = Math.round(y)
    L.b[at + 3] = w
    L.b[at + 4] = h
    L.icon[L.n] = icon
    L.n++
  }
  // Where on the rim a button of `size` sits, `angle` from straight down (to the right is positive).
  const spot = (angle: number, size: number) => {
    const at = r - size * 0.72
    return { x: cx + Math.sin(angle) * at - size / 2, y: cy + Math.cos(angle) * at - size / 2 }
  }
  // The next angle out from `from` (a button of `was` cells) where a button of `size` no longer touches it.
  const next = (from: number, was: number, size: number, dir: number) => {
    const a = spot(from, was)
    let angle = from
    for (let i = 0; i < 400; i++) {
      angle += dir * 0.01
      const b = spot(angle, size)
      const dx = Math.abs(b.x + size / 2 - (a.x + was / 2))
      const dy = Math.abs(b.y + size / 2 - (a.y + was / 2))
      if (Math.max(dx, dy) >= (size + was) / 2 + gap) break
    }
    return angle
  }
  let bottom = r // how far below the middle the play area may reach
  if (show) {
    const pause = spot(0, ps)
    add(START, pause.x, pause.y, ps, ps, ICON_PAUSE)
    if (dpad === 2) {
      const right = next(0, ps, bs, -1)
      const left = next(right, bs, bs, -1)
      const a = spot(left, bs)
      const b = spot(right, bs)
      add(LEFT, a.x, a.y, bs, bs, ICON_LEFT)
      add(RIGHT, b.x, b.y, bs, bs, ICON_RIGHT)
      L.dx = Math.round(a.x)
      L.dy = Math.round(Math.min(a.y, b.y))
      L.dw = Math.round(b.x) + bs - L.dx
      L.dh = Math.round(Math.max(a.y, b.y)) + bs - L.dy
    } else if (dpad === 4) {
      // A cross, smaller, on the rim down and to the left.
      const c = Math.max(Math.ceil(44 / px), Math.round(bs * 0.8))
      const at = spot(-0.62, c * 3)
      add(UP, at.x + c, at.y, c, c, ICON_UP)
      add(LEFT, at.x, at.y + c, c, c, ICON_LEFT)
      add(RIGHT, at.x + 2 * c, at.y + c, c, c, ICON_RIGHT)
      add(DOWN, at.x + c, at.y + 2 * c, c, c, ICON_DOWN)
      L.dx = Math.round(at.x)
      L.dy = Math.round(at.y)
      L.dw = 3 * c
      L.dh = 3 * c
    }
    if (actions >= 1) {
      // B nearer the middle and up the rim, A further out, as a thumb rolls.
      const first = next(0, ps, bs, 1)
      const p = spot(actions === 2 ? next(first, bs, bs, 1) : first, bs)
      if (actions === 2) {
        const q = spot(first, bs)
        add(B, q.x, q.y, bs, bs, ICON_B)
      }
      add(A, p.x, p.y, bs, bs, ICON_A)
    }
    for (let i = 0; i < L.n; i++) bottom = Math.min(bottom, L.b[i * 5 + 2] - cy - gap - 1)
  }
  // The play area: corners on the circle, the biggest that keeps above the buttons.
  let best = -1
  for (let a = 4; a < r; a++) {
    const b = Math.min(bottom, a)
    const hw = Math.floor(Math.sqrt(r * r - a * a))
    const h = Math.floor(a + b)
    const score = square ? Math.min(2 * hw, h) : hw * h
    if (score > best) {
      best = score
      L.x = Math.round(cx - hw)
      L.w = 2 * hw
      L.y = Math.round(cy - a)
      L.h = h
    }
  }
  if (name) {
    // The name in the arc above, where it fits.
    const y = Math.round((cy - r + L.y) / 2) - 2
    const half = Math.sqrt(Math.max(0, r * r - (cy - y) * (cy - y)))
    if (y > cy - r && textWidth(name, 1) < 2 * half - 2) {
      L.name = name
      L.nameX = Math.round(cx)
      L.nameY = y
    }
  }
  return L
}

/** What a pointer at (x, y) scene pixels presses: action bits, or 0 for the
 *  play area and the bare panels. */
export function hit(L: Layout, x: number, y: number): number {
  const cx = x / L.px
  const cy = y / L.px
  const g = L.gap
  // The D-pad as one pad: a direction by where on it the thumb is, so a
  // thumb rolling across it never falls between two buttons.
  if (L.dpad && cx >= L.dx - g && cx < L.dx + L.dw + g && cy >= L.dy - g && cy < L.dy + L.dh + g) {
    if (L.dpad === 2) return cx < L.dx + L.dw / 2 ? LEFT : RIGHT
    const mx = cx - (L.dx + L.dw / 2)
    const my = cy - (L.dy + L.dh / 2)
    const dead = L.dw / 6
    let bits = 0
    if (mx < -dead) bits |= LEFT
    if (mx > dead) bits |= RIGHT
    if (my < -dead) bits |= UP
    if (my > dead) bits |= DOWN
    return bits
  }
  for (let i = 0; i < L.n; i++) {
    const at = i * 5
    const bits = L.b[at]
    if (bits & (LEFT | RIGHT | UP | DOWN)) continue
    if (cx >= L.b[at + 1] - g && cy >= L.b[at + 2] - g && cx < L.b[at + 1] + L.b[at + 3] + g &&
        cy < L.b[at + 2] + L.b[at + 4] + g) return bits
  }
  return 0
}

/** Panels and every button. */
export function drawControls(L: Layout, held: number) {
  for (let i = 0; i < L.np; i++) {
    const at = i * 4
    const x = L.panels[at]
    const y = L.panels[at + 1]
    const w = L.panels[at + 2]
    const h = L.panels[at + 3]
    fill(x, y, w, h, UI_PANEL)
    // A line along the side that meets the play area.
    if (L.wide) fill(x === 0 ? x + w - 1 : x, y, 1, h, UI_EDGE)
    else fill(x, y, w, 1, UI_EDGE)
  }
  if (L.name) textCenter(L.name, L.nameX!, L.nameY!, 1, UI_BORDER)
  for (let i = 0; i < L.n; i++) drawButton(L, i, (held & L.b[i * 5]) !== 0)
}

/** Draws again only the buttons whose state changed between `was` and `now`. */
export function updateControls(L: Layout, was: number, now: number) {
  const changed = was ^ now
  if (!changed) return
  for (let i = 0; i < L.n; i++) if (changed & L.b[i * 5]) drawButton(L, i, (now & L.b[i * 5]) !== 0)
}

function drawButton(L: Layout, i: number, lit: boolean) {
  const at = i * 5
  const x = L.b[at + 1]
  const y = L.b[at + 2]
  const w = L.b[at + 3]
  const h = L.b[at + 4]
  box(x, y, w, h, lit ? UI_LIT : UI_FACE, UI_BORDER, UI_PANEL)
  const ink = lit ? UI_ICON_LIT : UI_ICON
  const cx = x + (w >> 1)
  const cy = y + (h >> 1) + (lit ? 1 : 0)
  const icon = L.icon[i]
  const r = Math.max(2, Math.round(w * 0.22))
  if (icon <= ICON_DOWN) arrow(icon, cx, cy, r, ink)
  else if (icon === ICON_PAUSE) {
    const bw = Math.max(1, Math.round(w / 7))
    fill(cx - bw - Math.max(1, bw >> 1), cy - r, bw, 2 * r, ink)
    fill(cx + Math.max(1, bw >> 1), cy - r, bw, 2 * r, ink)
  } else {
    const label = icon === ICON_A ? L.labelA : L.labelB
    // Letters about half the button's height, as wide as fit.
    let scale = Math.max(1, Math.floor((h * 0.5) / 5 + 0.5))
    while (scale > 1 && textWidth(label, scale) > w - 4) scale--
    text(label, cx - ((textWidth(label, scale) / 2) | 0), cy - ((5 * scale) >> 1), scale, ink)
  }
}

/** A filled triangle pointing `dir`, `r` cells from its tip to its base,
 *  centred on (cx, cy). */
function arrow(dir: number, cx: number, cy: number, r: number, v: number) {
  const half = (r + 1) >> 1
  for (let i = 0; i <= r; i++) {
    // i: how far from the tip; the span widens by one each side per step.
    if (dir === ICON_LEFT) fill(cx - half + i, cy - i, 1, 2 * i + 1, v)
    else if (dir === ICON_RIGHT) fill(cx + half - i, cy - i, 1, 2 * i + 1, v)
    else if (dir === ICON_UP) fill(cx - i, cy - half + i, 2 * i + 1, 1, v)
    else fill(cx - i, cy + half - i, 2 * i + 1, 1, v)
  }
}

sources.ui.ts:
// What the games share besides drawing and input: the palette slots of the
// controls and screens, the contrast rule, the cell size, the fixed-step
// clock, the random numbers, the high score table and the title, pause and
// game over screens. A game's own colors use palette indexes 0..223; the kit
// owns 224..255.
import { box, fill, textCenter, textWidth, title } from './gfx'

export const UI_TITLE = 224 // .. 228, a gradient down the title's letters
export const UI_SHADOW = 229
export const UI_ICON_LIT = 230
export const UI_PANEL = 231
export const UI_EDGE = 232
export const UI_BORDER = 233
export const UI_FACE = 234
export const UI_LIT = 235
export const UI_ICON = 236
export const UI_TEXT = 237
export const UI_DIM = 238
export const UI_BLINK = 239 // text that blinks: its color flips, no cell changes
export const UI_DIALOG = 240
export const UI_DIALOG_EDGE = 241
export const UI_ACCENT = 242
export const UI_GOOD = 243 // a new high score

/** A game's colors for the kit's slots, 0xRRGGBB. */
export type Theme = {
  title: number[] // five, top to bottom
  shadow: number
  panel: number
  edge: number
  border: number
  face: number
  lit: number
  icon: number
  iconLit: number
  text: number
  dim: number
  dialog: number
  dialogEdge: number
  accent: number
  good: number
}

const WHITE = 0xffffff
const BLACK = 0x000000

/** The kit's slots of `pal`, in the theme's colors or in black and white. */
export function uiColors(pal: Uint32Array, t: Theme, hc: boolean) {
  for (let i = 0; i < 5; i++) pal[UI_TITLE + i] = hc ? WHITE : t.title[i]
  pal[UI_SHADOW] = hc ? BLACK : t.shadow
  pal[UI_ICON_LIT] = hc ? BLACK : t.iconLit
  pal[UI_PANEL] = hc ? BLACK : t.panel
  pal[UI_EDGE] = hc ? WHITE : t.edge
  pal[UI_BORDER] = hc ? WHITE : t.border
  pal[UI_FACE] = hc ? BLACK : t.face
  pal[UI_LIT] = hc ? WHITE : t.lit
  pal[UI_ICON] = hc ? WHITE : t.icon
  pal[UI_TEXT] = hc ? WHITE : t.text
  pal[UI_DIM] = hc ? WHITE : t.dim
  pal[UI_BLINK] = hc ? WHITE : t.text
  pal[UI_DIALOG] = hc ? BLACK : t.dialog
  pal[UI_DIALOG_EDGE] = hc ? WHITE : t.dialogEdge
  pal[UI_ACCENT] = hc ? WHITE : t.accent
  pal[UI_GOOD] = hc ? WHITE : t.good
}

/** "Press A" text blinks by its palette entry alone. */
export function blink(pal: Uint32Array, now: number, on: number, off: number) {
  pal[UI_BLINK] = ((now / 450) | 0) & 1 ? off : on
}

// --- settings --------------------------------------------------------------

/** High contrast where the panel shows no color, or when asked. */
export function highContrast(contrast: any, frame: any): boolean {
  const mode = contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && frame.color === false)
}

/** Whether the panel can animate (an LCD, HDMI) rather than e-paper. */
export function fastScreen(frame: any): boolean {
  return frame.fast ?? !frame.paper
}

/** The "Pixel size" setting: a number, or about `across` cells over the
 *  short side for "auto". */
export function cellSize(setting: any, width: number, height: number, across: number): number {
  const asked = Number(setting) | 0
  if (asked >= 1) return Math.min(16, asked)
  return Math.max(2, Math.round(Math.min(width, height) / across))
}

/** One of `allowed`, else the first. */
export function choice(value: any, allowed: string[]): string {
  const s = String(value ?? '')
  return allowed.indexOf(s) >= 0 ? s : allowed[0]
}

// --- the clock ---------------------------------------------------------------

let last = 0
let owed = 0

/**
 * How many fixed steps of `stepMs` to run this frame, from the wall clock, so
 * the game keeps its speed at 12 fps and at 40. At most `cap` (a slow frame
 * slows the game rather than jumping it), none after a long gap (a pause, a
 * sleep).
 */
export function stepsDue(now: number, stepMs: number, cap: number): number {
  let gap = now - last
  last = now
  if (gap < 0 || gap > 400) gap = stepMs
  owed += gap
  let n = (owed / stepMs) | 0
  owed -= n * stepMs
  if (n > cap) {
    n = cap
    owed = 0
  }
  return n
}

/** Start counting from now (a new game, a resume). */
export function clockReset(now: number) {
  last = now
  owed = 0
}

// --- random numbers ----------------------------------------------------------

let seed = 1

export function reseed(s: number) {
  seed = s | 0 || 0x2545f491
}

/** An xorshift32: a 32-bit integer. */
export function rnd(): number {
  seed ^= seed << 13
  seed ^= seed >>> 17
  seed ^= seed << 5
  return seed
}

/** 0 .. n-1. */
export function rint(n: number): number {
  return ((rnd() >>> 0) % n) | 0
}

/** [0, 1). */
export function rfloat(): number {
  return (rnd() >>> 0) / 4294967296
}

// --- high scores -------------------------------------------------------------

/** The top five from the private `highScores` field (a JSON list of numbers). */
export function readScores(raw: any): number[] {
  let list = raw
  if (typeof list === 'string') {
    try {
      list = JSON.parse(list)
    } catch (e) {
      list = null
    }
  }
  const out: number[] = []
  if (Array.isArray(list)) for (const n of list) if (typeof n === 'number' && n > 0) out.push(n | 0)
  out.sort((a, b) => b - a)
  return out.slice(0, 5)
}

/** Puts `score` in the table: its place (0 = best), or -1 when it is not in
 *  the top five. Saves the table when it changed. */
export function addScore(list: number[], score: number): number {
  if (score <= 0) return -1
  let at = 0
  while (at < list.length && list[at] >= score) at++
  if (at >= 5) return -1
  list.splice(at, 0, score | 0)
  if (list.length > 5) list.length = 5
  frameos.setState('highScores', list.slice())
  return at
}

// --- screens -----------------------------------------------------------------

/** A dialog box: a border and a face. */
export function dialog(x: number, y: number, w: number, h: number) {
  fill(x, y, w, h, UI_DIALOG_EDGE)
  fill(x + 1, y + 1, w - 2, h - 2, UI_DIALOG)
}

/** The scale of the font that fits `chars` letters across `width` cells, at
 *  most `max`. */
export function fitScale(chars: number, width: number, max: number): number {
  return Math.max(1, Math.min(max, Math.floor(width / (chars * 4))))
}

/** The high score table, centred on `cx` from `y`: answers the rows it took. */
export function drawScores(list: number[], cx: number, y: number, scale: number, highlight = -1, label = 'HIGH SCORES'): number {
  textCenter(label, cx, y, scale, UI_ACCENT)
  if (!list.length) {
    textCenter('NONE YET', cx, y + 7 * scale, scale, UI_DIM)
    return 12 * scale
  }
  for (let i = 0; i < list.length; i++) {
    const line = String(i + 1) + '. ' + pad(list[i], 7)
    textCenter(line, cx, y + (7 + i * 7) * scale, scale, i === highlight ? UI_GOOD : UI_TEXT)
  }
  return (7 + list.length * 7) * scale
}

function pad(n: number, width: number): string {
  let s = String(n)
  while (s.length < width) s = ' ' + s
  return s
}

// The pause dialog's two buttons, for tapping: x, y, w, h each.
const choiceBoxes = new Int16Array(8)

/**
 * The pause dialog over the play area (x, y, w, h): PAUSED, and Resume and
 * Quit as big buttons. `hint` is a line of the keys, shown where it fits.
 * Another headline, a line under it and other buttons make it another
 * two-way choice (a rematch or the menu).
 */
export function drawPause(x: number, y: number, w: number, h: number, hint: string, head = 'PAUSED', line = '',
    first = 'RESUME', second = 'QUIT') {
  // Rows it takes at text scale s: 3 + 10 (the title, twice as big) + 4 + 11 + 3 + 11 + 3, 7 for the line
  // and 8 for the hint.
  const extra = line ? 7 : 0
  const s = Math.max(1, Math.min(Math.floor((w - 6) / 34), Math.floor((h - 4) / (45 + extra))))
  const ts = Math.max(1, Math.min(4, 2 * s, Math.floor((w - 8) / (head.length * 4))))
  const withHint = hint && h - 4 >= (45 + extra) * s + 8 && textWidth(hint, 1) <= w - 6
  const dw = Math.min(w - 2, Math.max(34 * s, textWidth(head, ts) + 6 * s, textWidth(line, s) + 6 * s,
    withHint ? textWidth(hint, 1) + 6 : 0))
  const dh = (45 + extra) * s + (withHint ? 8 : 0)
  const dx = x + ((w - dw) >> 1)
  const dy = y + ((h - dh) >> 1)
  dialog(dx, dy, dw, dh)
  const cx = dx + (dw >> 1)
  title(head, cx, dy + 3 * s, ts, UI_TITLE, UI_SHADOW)
  const bw = dw - 6 * s
  const bh = 11 * s
  const bx = dx + 3 * s
  let by = dy + 3 * s + 5 * ts + 4 * s
  if (line) {
    textCenter(line, cx, by - s, s, UI_TEXT)
    by += 7 * s
  }
  for (let i = 0; i < 2; i++) {
    box(bx, by, bw, bh, UI_FACE, UI_BORDER, UI_DIALOG)
    textCenter(i === 0 ? first : second, cx, by + 3 * s, s, UI_ICON)
    choiceBoxes[i * 4] = bx
    choiceBoxes[i * 4 + 1] = by
    choiceBoxes[i * 4 + 2] = bw
    choiceBoxes[i * 4 + 3] = bh
    by += bh + 3 * s
  }
  if (withHint) textCenter(hint, cx, dy + dh - 7, 1, UI_DIM)
}

/** Which of the pause dialog's buttons a tap at cell (cx, cy) is on: 1 Resume, 2 Quit, 0 neither. */
export function pauseChoice(cx: number, cy: number): number {
  for (let i = 0; i < 2; i++) {
    const at = i * 4
    if (cx >= choiceBoxes[at] && cy >= choiceBoxes[at + 1] && cx < choiceBoxes[at] + choiceBoxes[at + 2] &&
        cy < choiceBoxes[at + 1] + choiceBoxes[at + 3]) return i + 1
  }
  return 0
}

/**
 * Game over in a dialog over (x, y, w, h): the headline, a line or two about
 * the game, a new high score's place, as much of the table as fits, and
 * "tap" once `ready`.
 */
export function drawGameOver(x: number, y: number, w: number, h: number, head: string, lines: string[],
    rank: number, list: number[], ready: boolean, prompt = 'TAP OR PRESS A') {
  let widest = 15
  for (const line of lines) if (line.length > widest) widest = line.length
  const s = Math.max(1, Math.min(Math.floor((w - 6) / (widest * 4 + 4)), Math.floor((h - 4) / 60)))
  const big = Math.max(1, Math.min(2 * s, Math.floor((w - 8) / (head.length * 4))))
  // Rows: padding, the headline, the lines, the high score line, "tap".
  let need = 3 * s + 5 * big + 4 * s + lines.length * 7 * s + (rank >= 0 ? 7 * s : 0) + 9 * s
  const room = h - 4 - need - 7 * s
  const shown = Math.max(0, Math.min(list.length, Math.floor(room / (7 * s))))
  if (shown) need += (7 + shown * 7) * s + 2 * s
  const dw = Math.min(w - 2, Math.max(textWidth(head, big) + 8 * s, (widest * 4 + 4) * s))
  const dh = Math.min(h - 2, need)
  const dx = x + ((w - dw) >> 1)
  const dy = y + ((h - dh) >> 1)
  dialog(dx, dy, dw, dh)
  const cx = dx + (dw >> 1)
  title(head, cx, dy + 3 * s, big, UI_TITLE, UI_SHADOW)
  let ty = dy + 3 * s + 5 * big + 4 * s
  for (const line of lines) {
    textCenter(line, cx, ty, s, UI_TEXT)
    ty += 7 * s
  }
  if (rank >= 0) {
    textCenter(rank === 0 ? 'NEW HIGH SCORE!' : 'A HIGH SCORE!', cx, ty, s, UI_GOOD)
    ty += 7 * s
  }
  if (shown) {
    ty += 2 * s
    drawScores(list.slice(0, shown), cx, ty, s, rank)
  }
  if (ready) textCenter(prompt, cx, dy + dh - 8 * s, s, UI_BLINK)
}

/** For a screen that cannot animate (e-paper): what the game is and what it needs. */
export function drawSlowCard(cols: number, rows: number, name: string, about: string[], list: number[] | null) {
  fill(0, 0, cols, rows, UI_PANEL)
  const scale = fitScale(name.length + 2, cols - 4, 6)
  const small = fitScale(30, cols - 4, 3)
  // Everything in the middle of the screen.
  const tall = 8 * scale + about.length * 7 * small + (list ? (11 + Math.max(1, list.length) * 7) * small : 0)
  let y = Math.max(2, (rows - tall) >> 1)
  title(name, cols >> 1, y, scale, UI_TITLE, UI_SHADOW)
  y += 8 * scale
  for (const line of about) {
    textCenter(line, cols >> 1, y, small, UI_TEXT)
    y += 7 * small
  }
  y += 4 * small
  if (list) drawScores(list, cols >> 1, y, small)
}
